CREATE TABLE objection_codes (
    code        VARCHAR(6)    NOT NULL,
    kind        VARCHAR(20)   NOT NULL,
    concept     CHAR(2)       NOT NULL,
    group_code  CHAR(4)       NOT NULL,
    applicable  BOOLEAN       NOT NULL,
    description VARCHAR(400)  NOT NULL,

    CONSTRAINT pk_objection_codes PRIMARY KEY (code),
    CONSTRAINT chk_objection_codes_kind CHECK (kind IN ('DEVOLUTION', 'GLOSS', 'RESPONSE')),
    CONSTRAINT chk_objection_codes_code CHECK (REGEXP_LIKE(code, '^(DE|FA|TA|SO|AU|CO|CL|SA|RE)[0-9]{2}([0-9]{2})?$', 'c')),
    CONSTRAINT chk_objection_codes_group CHECK (group_code = LEFT(code, 4) AND concept = LEFT(code, 2)),
    CONSTRAINT chk_objection_codes_applicable CHECK (applicable = (CHAR_LENGTH(code) = 6))
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COLLATE = utf8mb4_0900_ai_ci;

